      'hi': 'कहने का प्रयास करें: \"सुरेश के लिए 2 लीटर दूध डालें\"',
      'it': 'Prova a dire: \"Aggiungi 2 litri di latte per Suresh\"',
      'kn': '\"ಸುರೇಶನಿಗೆ 2 ಲೀಟರ್ ಹಾಲು ಸೇರಿಸಿ\" ಎಂದು ಹೇಳಿ ನೋಡಿ.',
      'ml': '\"സുരേഷിന് 2 ലിറ്റർ പാൽ ചേർക്കൂ\" എന്ന് പറഞ്ഞു നോക്കൂ',
      'mr': '\"सुरेशसाठी २ लिटर दूध घाला\" असे म्हणण्याचा प्रयत्न करा.',
      'or': 'କହିବାକୁ ଚେଷ୍ଟା କରନ୍ତୁ: \"ସୁରେଶ ପାଇଁ 2 ଲିଟର କ୍ଷୀର ଯୋଡନ୍ତୁ\"',
      'pa': 'ਇਹ ਕਹਿਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰੋ: \"ਸੁਰੇਸ਼ ਲਈ 2 ਲੀਟਰ ਦੁੱਧ ਪਾਓ\"',
      'pl': 'Spróbuj powiedzieć: „Dodaj 2 litry mleka dla Suresha”',
      'pt': 'Tente dizer: \"Adicione 2 litros de leite para Suresh\"',
      'ru': 'Попробуйте сказать: «Добавь 2 литра молока для Суреша».',
      'ta': '\"சுரேஷ்க்கு 2 லிட்டர் பால் சேர்\"னு சொல்லிப் பாருங்க.',
      'te': '\"సురేష్ కోసం 2 లీటర్ల పాలు కలపండి\" అని చెప్పి ప్రయత్నించండి',
    },
